  const [discount, setDiscount] = useState({ code: "", type: "percent" as "percent" | "fixed", value: "10", minOrderAmount: "0", maxUses: "", startsAt: "", endsAt: "" });
  const [editingDiscountId, setEditingDiscountId] = useState<number | null>(null);
  const [search, setSearch] = useState("");
